/* ---------------- estilos ---------------- */

/* Botón base de toda la app: superficie oscura, borde fino, esquinas amplias, ícono + texto centrados.
   (mismo aspecto que "Aplicar descuento"). Los botones secundarios lo comparten; el principal usa el color de acento. */
/* Medidas únicas de la app (un solo alto y un par de radios, para que todo se sienta de la misma familia):
 *   botones de acción 44 px · esquinas 12      ·  chips y filtros 36 px · totalmente redondeados
 *   los botones secundarios son "tonales" (relleno suave, sin borde); el borde queda solo para tarjetas y campos de texto. */
export const ALTO_BOTON = 44;
export const ALTO_CHIP = 36;
export const RADIO_BOTON = 12;

const botonBase = {
  display: "flex", alignItems: "center", justifyContent: "center", gap: 10,
  padding: "11px 16px", minHeight: ALTO_BOTON, width: "100%",
  background: "var(--c-ede7d8-b)", color: "var(--c-242019-t)",
  border: "none", borderRadius: RADIO_BOTON,
  fontSize: 14.5, fontWeight: 600, letterSpacing: 0.1, textAlign: "center",
  cursor: "pointer",
};

